content.referenceSolution:
function parsePositiveInt(text) {
  if (typeof text !== 'string' || !/^\d+$/.test(text) || text === '0') {
    throw new Error('invalid');
  }
  return Number(text);
}
function classifyParsePositive(text) {
  try {
    return { ok: true, value: parsePositiveInt(text) };
  } catch (e) {
    if (e instanceof Error && e.message === 'invalid') {
      return { ok: false, message: 'invalid' };
    }
    throw e;
  }
}

